import { useEffect,useState } from "react";
interface Props{design_id:number;revision_id?:number;projectId?:string;preview?:boolean}
export default function PCBDesignCard({design_id,projectId="",preview}:Props){const [design,setDesign]=useState<any>(preview?{name:"Controller board",status:"validated",current_revision:{number:3,definition:{board:{width_nm:50000000,height_nm:30000000},components:[{},{},{}],nets:[{},{}],traces:[{}]}},validation:{status:"passed",errors:0,warnings:1}}:null);useEffect(()=>{if(preview||!design_id)return;fetch(`/api/apps/pcb/api/designs/${design_id}?project_id=${encodeURIComponent(projectId)}`,{credentials:"same-origin"}).then(r=>r.json()).then(j=>setDesign(j.design)).catch(()=>setDesign(null))},[design_id,projectId,preview]);if(!design)return <div className="rounded-lg border border-border p-3 text-xs text-text-muted">PCB design unavailable</div>;const def=design.current_revision?.definition;return <div className="min-w-[290px] overflow-hidden rounded-xl border border-border bg-bg"><div className="relative h-24 bg-[#0c1717] p-3"><svg viewBox="0 0 50 28" className="h-full w-full"><rect x="3" y="2" width="44" height="24" rx="2" fill="#123a32" stroke="#53dfac" strokeWidth=".4"/><path d="M8 15H22L28 9H42M28 9v10h14" fill="none" stroke="#ff6b5e" strokeWidth=".8" strokeLinecap="round"/><rect x="20" y="11" width="8" height="6" rx="1" fill="#e8f1ed"/><circle cx="8" cy="15" r="1.2" fill="#d9b45b"/></svg><span className="absolute right-2 top-2 rounded bg-black/40 px-1.5 py-1 text-[9px] text-[#74e7bd]">native</span></div><div className="p-3"><div className="flex items-center gap-2"><strong className="text-sm">{design.name}</strong><span className="ml-auto text-[10px] text-text-muted">r{design.current_revision?.number}</span></div><div className="mt-2 flex gap-2 text-[10px] text-text-muted"><span>{def?`${def.board.width_nm/1e6} × ${def.board.height_nm/1e6} mm`:"PCB"}</span><span>·</span><span>{def?.components?.length||0} parts</span><span className={design.validation?.status==="passed"?"ml-auto text-green":"ml-auto"}>● {design.validation?.status||design.status}</span></div></div></div>}
